<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {api} from '../api'
import {ElMessage} from 'element-plus'
import type {Evaluation,Evidence} from '../types'
import EvaluationReview from './EvaluationReview.vue'
import ReportText from './ReportText.vue'
const props=defineProps<{value:Evaluation,reportId?:string,siblings?:any[]}>()
const emit=defineEmits<{changed:[]}>()
const selected=ref<Evidence|null>(null),levelsOpen=ref(false),legacyTask=ref<any>(null),draft=ref('')
const sourceContext=ref<any>(null),sourceError=ref(''),sourceLoading=ref(false)
let sourceRequest=0
watch(selected,()=>{sourceRequest++;sourceContext.value=null;sourceError.value='';sourceLoading.value=false})
async function previewSource(){const id=selected.value?.id;if(!props.reportId||!id)return;const token=++sourceRequest;sourceLoading.value=true;try{const data=await api('/reports/'+props.reportId+'/evidence/'+encodeURIComponent(id)+'/context');if(token===sourceRequest)sourceContext.value=data}catch(e){if(token===sourceRequest)sourceError.value=(e as Error).message}finally{if(token===sourceRequest)sourceLoading.value=false}}
const levels=['成果形成与验证','局部作用验证','外部应用验证','专业方向显著影响','领域基础能力','重大引领影响']
const states:Record<string,string>={verified:'有依据支持',possibly_happened_but_unverified:'存在待核线索',not_found_as_of_cutoff:'已查范围内未发现',conflict:'存在相反依据'}
const axes:Record<string,string>={scientific_or_technical_value:'科学与技术价值',project_additionality:'项目新增',ai_contribution:'AI贡献',future_potential:'未来潜力',management_action:'管理建议'}
const auditStates:Record<string,string>={assessed:'已评定',insufficient_evidence:'证据不足',not_applicable:'不适用',conflict:'存在冲突',not_assessed:'尚未审阅'}
const facts=computed(()=>props.value.fact_ledger?.impact_facts||[])
const attained=computed(()=>facts.value.filter((f:any)=>(props.value.attainment_fact_ids||[]).includes(f.id)))
const status=computed(()=>props.value.adjudication_status==='expert_confirmed'?'专家已确认':props.value.adjudication_status==='formal'?'正式认定':'系统初步判断')
function sourceLabel(value:string){return ({independent:'独立来源',related:'关联来源',project:'项目方',unknown:'未确认',full_text:'已取得正文',abstract:'仅取得摘要',metadata_only:'仅元数据',blocked:'访问受阻',eligible:'符合本轮时间要求',unknown_date:'日期不明',after_cutoff:'截止日之后',not_verified:'尚未通过核验'} as Record<string,string>)[value]||value}
function openEvidence(id:string){const ev=props.value.evidence.find(e=>e.id===id);if(ev)selected.value=ev;else ElMessage.error('未找到该来源，请核对报告引用')}
function openTask(t:any){legacyTask.value=t;draft.value=t.body||t.detail}
async function copy(){try{await navigator.clipboard.writeText(draft.value);ElMessage.success('已复制')}catch{ElMessage.error('复制失败，请手动选择文案')}}
</script>
<template>
<div class="teacher-report">
  <el-alert v-if="value.is_demo" title="演示结果，内容不代表真实科研结论" type="warning" :closable="false"/>
  <div class="teacher-layout">
    <aside class="teacher-sidebar">
      <section class="teacher-card"><h2>成果</h2><nav v-if="siblings?.length"><RouterLink v-for="item in siblings" :key="item.id" :to="'/results/'+item.id" :class="{active:item.id===reportId}">{{item.title}}</RouterLink></nav><p v-else>{{value.title}}</p><details><summary>成果信息</summary><p>{{value.project_name}}</p><p>{{value.category}}</p><p v-if="value.outcome_object">主对象：{{value.outcome_object.name}} · {{value.outcome_object.version}}</p><p>{{value.fact_ledger?.primary_object_id ? '已锁定主评价对象' : '历史报告，沿用原评价范围'}}</p><p v-for="c in value.candidates" :key="c">{{c}}</p></details></section>
      <section class="teacher-card"><h2>送检材料与证据 <small>{{value.evidence.length}}</small></h2><button v-for="ev in value.evidence.slice(0,3)" :key="ev.id" class="source-index" @click="selected=ev"><strong>{{ev.title}}</strong><span>{{ev.source}}</span></button><details v-if="value.evidence.length>3"><summary>展开其余 {{value.evidence.length-3}} 条来源</summary><button v-for="ev in value.evidence.slice(3)" :key="ev.id" class="source-index" @click="selected=ev"><strong>{{ev.title}}</strong><span>{{ev.source}}</span></button></details><p v-if="!value.evidence.length">暂无可展示来源。</p></section>
    </aside>
    <article class="teacher-body">
      <section class="teacher-card"><h2>① 影响力判断</h2><p class="teacher-meta">{{value.project_name}} · {{value.category}}</p><h1>{{value.title}}</h1><div class="teacher-meta">评价截止：{{value.evaluation_cutoff||'历史报告未单列截止日'}} <span class="state-chip">{{status}}</span></div><p v-if="value.evaluation_started_at" class="teacher-meta">本次评价运行：{{new Date(value.evaluation_started_at).toLocaleString()}}</p><p v-if="value.review_window" class="teacher-meta">{{value.review_window}}</p><div class="fact-summary"><strong>核心判断</strong><p>{{value.summary}}</p></div>
        <div class="teacher-level"><div class="level-emphasis"><span>当前影响等级</span><div class="level-number">{{value.level?'L'+value.level:'待核验'}} <button class="scale-help" @click="levelsOpen=true" aria-label="查看六级影响力标尺">?</button></div><strong>{{value.level_name}}</strong></div><div><h3>{{value.level?'支持当前判断的关键事实':'当前已掌握的事实与边界'}}</h3><div v-for="f in attained" :key="f.id" class="fact-item"><p>{{f.fact_text}}</p><button v-for="id in f.evidence_ids" :key="id" class="source-tag" @click="openEvidence(id)">{{value.evidence.find(e=>e.id===id)?.title||'来源缺失'}}</button></div><template v-if="!attained.length"><div v-for="(r,i) in value.reasons" :key="i" class="fact-item"><p>{{r}}</p><button v-for="id in value.reason_evidence_refs?.[i]||[]" :key="id" class="source-tag" @click="openEvidence(id)">{{value.evidence.find(e=>e.id===id)?.title||'来源缺失'}}</button></div></template><div v-if="value.boundary_gap" class="boundary"><strong>当前证据边界</strong><p v-for="(part,i) in value.boundary_gap.match(/[^。]+。|[^。]+$/g)||[]" :key="i">{{part}}</p></div></div></div>
        <div v-if="value.level&&value.upgrades?.length" class="stage-references"><div v-for="(u,i) in value.upgrades" :key="u.target_level"><small>{{i===0?'下一阶段条件参考':'更高阶段参考'}}</small><h3>L{{u.target_level}} · {{u.level_name}}</h3><p>{{u.need}}</p><details><summary>对应核验材料</summary><ul><li v-for="material in u.proof_materials" :key="material">{{material}}</li></ul></details></div></div><p v-if="value.level===6" class="teacher-meta">后续关注作用的持续性、范围变化及新的反证。</p>
      </section>
      <section class="teacher-card"><h2>② 关键判断与证据</h2><p class="teacher-meta">先看核验结论，再按需查阅项目主张和原始依据。</p><div v-for="(row,index) in value.dimensions" :key="row.topic" class="judgment-card"><header><span class="judgment-number">0{{index+1}}</span><h3>{{row.topic}}</h3></header><div class="judgment-conclusion"><small>评价核验</small><ReportText :text="row.assessment"/><div class="source-links"><button v-for="id in row.evidence_ids" :key="id" class="source-tag" @click="openEvidence(id)">{{value.evidence.find(e=>e.id===id)?.title||'来源缺失'}}</button></div></div><details class="project-claim"><summary>对照项目方主张</summary><ReportText :text="row.claim"/><button v-for="id in row.project_evidence_ids||[]" :key="id" class="source-tag" @click="openEvidence(id)">{{value.evidence.find(e=>e.id===id)?.title||'来源缺失'}}</button></details></div>
        <details v-if="value.fact_ledger"><summary>查看分项判断与事实状态</summary><div v-for="(label,key) in axes" :key="key" class="fact-item"><h3>{{label}}</h3><ReportText :text="value.fact_ledger.value_and_attribution[key]?.conclusion"/><p class="teacher-meta">{{value.fact_ledger.value_and_attribution[key]?.limitations.join('；')}}</p><button v-for="id in value.fact_ledger.value_and_attribution[key]?.evidence_ids||[]" :key="id" class="source-tag" @click="openEvidence(id)">{{value.evidence.find(e=>e.id===id)?.title||'来源缺失'}}</button></div><div v-for="f in facts" :key="f.id" class="fact-item"><span class="state-chip">{{states[f.state]||(f.assessment_status==='not_applicable'?'不适用':'尚未核验')}}</span><p>{{f.fact_text}}</p><p class="teacher-meta">{{f.time_basis}} {{f.notes}}</p><button v-for="id in [...f.evidence_ids,...f.counter_evidence_ids]" :key="id" class="source-tag" @click="openEvidence(id)">{{value.evidence.find(e=>e.id===id)?.title||'来源缺失'}}</button></div></details>
        <details v-if="value.dimension_audit?.length"><summary>查看七维审阅底稿</summary><div v-for="d in value.dimension_audit" :key="d.id" class="fact-item"><strong>{{d.id}} · {{d.grade||auditStates[d.assessment_state]||'历史未记录状态'}}</strong><ReportText :text="d.conclusion"/><p class="teacher-meta">{{d.gaps?.join('；')}}</p><button v-for="id in d.evidence_ids" :key="id" class="source-tag" @click="openEvidence(id)">{{value.evidence.find(e=>e.id===id)?.title||'来源缺失'}}</button></div></details>
      </section>
      <section class="teacher-card"><h2>③ 下一步任务</h2><EvaluationReview v-if="reportId" :report-id="reportId" :value="value" @changed="emit('changed')"/><template v-else><div v-for="(item,i) in value.follow_ups" :key="i" class="task-item"><div><h3>{{item.title}}</h3><p>{{item.detail}}</p></div><el-button @click="openTask(item)">查看任务</el-button></div><p v-if="!value.follow_ups.length">当前无必须补充事项。</p></template></section>
    </article>
  </div>
  <el-dialog :model-value="!!selected" @close="selected=null" title="证据来源与证明边界" width="min(800px,94vw)"><template v-if="selected"><h2>{{selected.title}}</h2><p>{{selected.source}} · {{selected.locator}}</p><p class="teacher-meta">{{selected.verification==='verified'?'已取得来源依据':selected.verification==='project_statement'?'项目材料原文，不等于独立认证':'尚未完成原文核验'}}</p><p v-if="selected.date" class="teacher-meta">来源日期：{{selected.date}}</p><dl v-if="selected.source_context" class="teacher-meta"><template v-for="(label,key) in {event_date:'事件日期',first_public_date:'首次公开',accessed_at:'取得日期',access_status:'正文取得情况',relationship:'来源关系'}" :key="key"><template v-if="selected.source_context[key]"><dt>{{label}}</dt><dd>{{sourceLabel(selected.source_context[key])}}</dd></template></template></dl><p v-if="selected.time_eligibility" class="teacher-meta">本轮时间资格：{{sourceLabel(selected.time_eligibility)}}</p><blockquote>{{selected.excerpt}}</blockquote><div v-for="f in facts.filter((f:any)=>[...f.evidence_ids,...f.counter_evidence_ids].includes(selected!.id))" :key="f.id" class="teacher-meta">关联事实：{{f.fact_text}} · {{f.time_basis}}</div><p>能证明：{{selected.supports||'历史记录未单列'}}</p><p>不能证明：{{selected.does_not_prove||'需结合对象、时间和上下文判断'}}</p><div v-if="reportId&&selected.material_id"><el-button :loading="sourceLoading" @click="previewSource">在材料文本中定位引文</el-button><p v-if="sourceError" role="alert">{{sourceError}}</p><div v-if="sourceContext" class="source-context"><p class="teacher-meta">{{sourceContext.filename}} · {{sourceContext.note}}</p><pre v-if="sourceContext.matched">{{sourceContext.before}}<mark>{{sourceContext.matched_text||sourceContext.quote}}</mark>{{sourceContext.after}}</pre></div></div><p v-if="reportId&&selected.material_id"><a :href="`/api/reports/${reportId}/materials/${selected.material_id}`">下载送检原文件 ↗</a></p><a v-if="selected.url" :href="selected.url" target="_blank" rel="noopener noreferrer">打开原始来源 ↗</a></template></el-dialog>
  <el-dialog v-model="levelsOpen" title="六级影响力状态" width="min(700px,94vw)"><div v-for="(name,i) in levels" :key="name" class="scale-row"><strong>L{{i+1}}</strong><span>{{name}}</span></div><p>等级记录已发生且有依据的作用，七维用于证据审阅；不求平均，不要求所有成果逐级经历。</p></el-dialog>
  <el-dialog :model-value="!!legacyTask" @close="legacyTask=null" title="任务文案预览" width="min(700px,94vw)"><el-input v-model="draft" type="textarea" :rows="12"/><el-button @click="copy">复制当前文案</el-button><p class="teacher-meta">当前为管理员预览；持久化任务与专家复核请在已发布报告中操作。</p></el-dialog>
</div>
</template>
<style scoped>
.teacher-report{color:#29465d;line-height:1.75;overflow-wrap:anywhere}.teacher-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:20px}.teacher-sidebar,.teacher-body{display:flex;flex-direction:column;gap:20px;min-width:0}.teacher-card{background:white;border:1px solid #dce6f0;border-radius:10px;padding:24px;min-width:0}.teacher-card h2{font-size:18px;margin:0 0 20px;color:#264f75}.teacher-card h1{font-size:26px;line-height:1.4;margin:8px 0}.teacher-card h3{font-size:15px;margin:8px 0}.teacher-meta{font-size:12px;color:#617b8f}.state-chip{display:inline-block;border:1px solid #cbdfe9;border-radius:12px;padding:1px 10px;font-size:12px;color:#366982;background:#f5faff}.fact-summary{background:#f6f9fd;border-left:3px solid #a0bad7;padding:14px;margin:20px 0}.teacher-level{display:grid;grid-template-columns:180px minmax(0,1fr);gap:24px}.level-emphasis{border-right:1px solid #e0e8f0;padding-right:20px}.level-number{font-size:48px;line-height:1.5;color:#287960;font-weight:650}.scale-help{font:14px system-ui;border:1px solid #a5b9ca;border-radius:50%;background:white;color:#426382;cursor:pointer}.boundary{border-left:3px solid #c88927;background:#fffaf2;padding:12px;margin-top:16px}.boundary p,.fact-item p{margin:6px 0}.fact-item{padding:10px 0}.stage-references{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:24px}.stage-references>div{border:1px solid #dce6f0;background:#fbfdff;padding:16px;border-radius:7px}.source-index{display:block;text-align:left;width:100%;padding:12px 0;border:0;border-bottom:1px solid #edf1f5;background:none;color:#2e597e;cursor:pointer;overflow-wrap:anywhere}.source-index strong,.source-index span{display:block}.source-index span{font-size:11px;color:#71889b}.source-tag{font:12px system-ui;color:#326b9e;border:1px solid #c6d9ec;border-radius:4px;background:white;padding:4px 8px;margin:3px 5px 3px 0;cursor:pointer;max-width:100%;overflow-wrap:anywhere;white-space:normal}.comparison-head,.comparison-row{display:grid;grid-template-columns:130px minmax(0,1fr) minmax(0,1fr)}.comparison-head{font-size:13px;color:#64809b}.comparison-row{border-top:1px solid #e2eaf2;margin-top:12px}.comparison-row>div,.comparison-row>h3{padding:14px;margin:0;min-width:0}.comparison-row small{display:none}.evaluation-column{background:#f5f9fe}.comparison-row p{margin:0 0 10px;font-size:14px}.task-item{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #e2eaf2;padding:12px 0}details{margin-top:18px;border-top:1px solid #e2eaf2;padding-top:12px}summary{cursor:pointer;color:#326b9e}blockquote{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f8fc;border-left:3px solid #a0bcd8;margin:16px 0;padding:16px}.scale-row{display:flex;gap:20px;padding:10px}.teacher-sidebar nav a{display:block;padding:12px;margin:8px 0;border:1px solid #d9e4f1;border-radius:6px;color:#335977;text-decoration:none}.teacher-sidebar nav a.active{background:#eef5fe;border-color:#99bdec}@media(max-width:1150px){.teacher-layout{grid-template-columns:220px minmax(0,1fr)}.teacher-card{padding:18px}.teacher-level{grid-template-columns:140px minmax(0,1fr)}.comparison-head,.comparison-row{grid-template-columns:110px minmax(0,1fr) minmax(0,1fr)}}@media(max-width:900px){.teacher-layout{grid-template-columns:1fr}.teacher-sidebar{display:contents}.teacher-sidebar>section:first-child{grid-row:1}.teacher-body{grid-row:2}.teacher-sidebar>section:last-child{grid-row:3}.comparison-head{display:none}.comparison-row{grid-template-columns:1fr}.comparison-row small{display:block;color:#617b8f}.teacher-sidebar nav{max-height:200px;overflow:auto}}@media(max-width:560px){.teacher-sidebar,.teacher-level,.stage-references{grid-template-columns:1fr}.level-emphasis{border-right:0;border-bottom:1px solid #e0e8f0;padding-bottom:16px}.teacher-card{padding:16px}.teacher-card h1{font-size:22px}}
.judgment-card{border:1px solid #e1e9ef;border-radius:8px;margin:18px 0;overflow:hidden}.judgment-card header{display:flex;align-items:center;gap:12px;padding:14px 18px;background:#f4f8fb}.judgment-card header h3{margin:0;font-size:16px}.judgment-number{color:#488ba7;font-size:13px;font-weight:700}.judgment-conclusion{padding:14px 20px}.judgment-conclusion>small{color:#4b7985;font-size:12px}.project-claim{margin:0 20px 16px;padding-top:12px;border-top:1px solid #e7edf2}.project-claim summary{font-size:13px;color:#647b8e}.source-links{display:flex;flex-wrap:wrap;gap:4px}.fact-summary p{margin:8px 0 0}.teacher-card>details{border-top:1px solid #e1e9ef;padding:14px 0;margin-top:14px}.teacher-report summary:focus-visible{outline:2px solid #28688a;outline-offset:3px}@media(max-width:700px){.judgment-conclusion{padding:12px 16px}}
.source-context pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.9 system-ui;background:#f5f8fb;padding:16px;max-height:360px;overflow:auto}.source-context mark{background:#ffebb0;color:#433812}
</style>
